#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.277777685, -0.35694437, 4.500000000406956e-08], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.06944446500000001, 'zmax': 0.06944446499999998, 'profiles': [{'outer': [[-0.272487625, -0.03314910999999998], [-0.257439835, -0.010615600000000003], [-0.234906345, 0.0044321900000000025], [-0.208328975, 0.009722220000000004], [-0.181760115, 0.0044321900000000025], [-0.159226615, -0.010615569999999963], [-0.14417882499999998, -0.03314908], [-0.13888880999997735, -0.05971789466342384], [-0.133598785, -0.03314910999999998], [-0.118551005, -0.010615569999999963], [-0.096017515, 0.0044321900000000025], [-0.069440145, 0.009722220000000004], [-0.042871295, 0.004432219999999987], [-0.020337774999999995, -0.010615569999999963], [-0.005290004999999996, -0.03314908], [1.9999957471189284e-08, -0.059717864663323864], [0.005290015000000004, -0.03314908], [0.020337795000000006, -0.010615539999999979], [0.04287131500000001, 0.0044322500000000264], [0.06944863500000001, 0.009722280000000028], [0.096017525, 0.0044322500000000264], [0.118551035, -0.010615539999999979], [0.133598815, -0.03314905000000001], [0.1388888279865518, -0.05971777432682492], [0.144178825, -0.03314905000000001], [0.15922661500000002, -0.010615539999999979], [0.181760115, 0.0044322500000000264], [0.208337475, 0.009722280000000028], [0.234906365, 0.0044322500000000264], [0.257439835, -0.010615509999999995], [0.272487625, -0.033149019999999974], [0.277777655, -0.05971788], [0.272487655, -0.08629523], [0.257439865, -0.10882873999999998], [0.23490639500000002, -0.12387651999999999], [0.208337505, -0.12916655999999999], [0.181760145, -0.12387654999999997], [0.159226645, -0.10882876999999996], [0.144178855, -0.08629525999999998], [0.13888882201449368, -0.05971807572111523], [0.133598845, -0.08629523], [0.118551065, -0.10882876999999996], [0.096017525, -0.12387654999999997], [0.06944863500000001, -0.12916658999999997], [0.04287131500000001, -0.12387654999999997], [0.020337805000000004, -0.1088288], [0.005290015000000004, -0.08629525999999998], [1.999996593704938e-08, -0.05971801536070715], [-0.005290004999999996, -0.08629528999999997], [-0.020337764999999997, -0.1088288], [-0.042871284999999995, -0.12387658000000001], [-0.06944012499999999, -0.12916662], [-0.09601750499999999, -0.12387658000000001], [-0.118551015, -0.10882882999999999], [-0.133598785, -0.08629532000000001], [-0.13888880999999428, -0.05971804536056471], [-0.14417882499999998, -0.08629528999999997], [-0.159226595, -0.1088288], [-0.181760135, -0.12387661], [-0.208328995, -0.12916665], [-0.234906335, -0.12387661], [-0.257439835, -0.10882882999999999], [-0.27248759499999997, -0.08629532000000001], [-0.277777655, -0.05971799999999999]], 'holes': []}, {'outer': [[-0.187995435, 0.10882879000000001], [-0.165461895, 0.1238766], [-0.138884555, 0.12916665000000002], [-0.112315705, 0.12387662000000002], [-0.089782195, 0.10882883000000002], [-0.074734415, 0.08629532000000001], [-0.06944439701338703, 0.05972652033651952], [-0.064154375, 0.08629529000000002], [-0.049106584999999994, 0.10882883000000002], [-0.026573074999999995, 0.12387662000000002], [4.26500000000407e-06, 0.12916665000000002], [0.026573125000000003, 0.12387663000000002], [0.049106645000000004, 0.10882885], [0.064154405, 0.08629532000000001], [0.069444435, 0.05972646000000004], [0.064154405, 0.03314911000000004], [0.049106645000000004, 0.010615600000000003], [0.026573095000000005, -0.004432180000000008], [4.235000000004069e-06, -0.009722220000000004], [-0.026573104999999996, -0.004432180000000008], [-0.049106615, 0.010615580000000013], [-0.064154375, 0.03314908], [-0.06944440298563055, 0.05972636963937858], [-0.074734415, 0.03314911000000004], [-0.089782185, 0.010615600000000003], [-0.112315695, -0.004432180000000008], [-0.138884585, -0.009722249999999988], [-0.165461915, -0.004432209999999992], [-0.187995415, 0.010615580000000013], [-0.203043195, 0.03314908], [-0.208333235, 0.05972640000000001], [-0.203043205, 0.08629529000000002]], 'holes': []}, {'outer': [[0.089782255, 0.10882885], [0.112315755, 0.12387662000000002], [0.138893115, 0.12916665000000002], [0.165461945, 0.12387662000000002], [0.187995475, 0.10882886], [0.20304323500000002, 0.08629532000000001], [0.208333295, 0.05972646000000004], [0.20304323500000002, 0.03314914000000002], [0.187995475, 0.010615600000000003], [0.16546191500000001, -0.004432180000000008], [0.138893085, -0.009722220000000004], [0.112315725, -0.004432180000000008], [0.08978222500000001, 0.010615580000000013], [0.074734435, 0.03314911000000004], [0.069444435, 0.05972643], [0.074734435, 0.08629529000000002]], 'holes': []}], 'simplify_tolerance': 0.00011111106200000001, 'sketch_entity_count': 112}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
